mapper.delete:
DELETE FROM traveler_profile
WHERE id IN (
    SELECT tp.id
    FROM traveler_profile tp
    WHERE tp.updated_at  <  #{retainedAfter}
      AND NOT EXISTS (
          SELECT 1 FROM journey_session js WHERE js.traveler_profile_id = tp.id
      )
    ORDER BY tp.updated_at ASC, tp.id ASC
    LIMIT #{limit}
)
